const http = require('http');
const html = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>TERROIR \u2014 Specialty Coffee</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n  <link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,700;0,900;1,400;1,700&family=DM+Mono:ital,wght@0,300;0,400;0,500;1,300&family=Crimson+Pro:ital,wght@0,300;0,400;0,600;1,300;1,400&display=swap\" rel=\"stylesheet\" />\n  <style>\n    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n\n    :root {\n      --espresso:   #120b07;\n      --roast:      #1e1008;\n      --bark:       #2d1a0d;\n      --mahogany:   #4a2412;\n      --amber:      #c8720a;\n      --gold:       #e8a020;\n      --cream:      #f4e4cc;\n      --parchment:  #fdf6ed;\n      --fog:        #b09070;\n      --rust:       #c84820;\n      --white:      #fff8f0;\n    }\n\n    html { scroll-behavior: smooth; }\n\n    body {\n      background: var(--espresso);\n      color: var(--cream);\n      font-family: 'Crimson Pro', Georgia, serif;\n      font-size: 18px;\n      line-height: 1.6;\n      overflow-x: hidden;\n      cursor: none;\n    }\n\n    /* \u2500\u2500 Custom cursor \u2500\u2500 */\n    .cursor {\n      position: fixed; top: 0; left: 0; z-index: 9999;\n      pointer-events: none; mix-blend-mode: exclusion;\n    }\n    .cursor-dot {\n      width: 8px; height: 8px; border-radius: 50%;\n      background: var(--gold);\n      transform: translate(-50%, -50%);\n      transition: transform 0.1s ease;\n    }\n    .cursor-ring {\n      position: fixed; top: 0; left: 0;\n      width: 36px; height: 36px; border-radius: 50%;\n      border: 1.5px solid var(--amber);\n      transform: translate(-50%, -50%);\n      pointer-events: none; z-index: 9998;\n      transition: transform 0.25s cubic-bezier(.16,1,.3,1), width 0.25s, height 0.25s, border-color 0.25s;\n    }\n    body.hovering .cursor-ring {\n      width: 60px; height: 60px;\n      border-color: var(--gold);\n    }\n\n    /* \u2500\u2500 Grain overlay \u2500\u2500 */\n    body::before {\n      content: '';\n      position: fixed; inset: 0; z-index: 9990;\n      pointer-events: none;\n      background-image: url(\"data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='1'/%3E%3C/svg%3E\");\n      opacity: 0.035;\n    }\n\n    /* \u2500\u2500 Nav \u2500\u2500 */\n    nav {\n      position: fixed; top: 0; left: 0; right: 0; z-index: 100;\n      display: flex; justify-content: space-between; align-items: center;\n      padding: 28px 56px;\n      background: linear-gradient(to bottom, rgba(18,11,7,0.9) 0%, transparent 100%);\n      backdrop-filter: blur(0px);\n      transition: backdrop-filter 0.4s, padding 0.4s;\n    }\n    nav.scrolled {\n      padding: 18px 56px;\n      backdrop-filter: blur(16px);\n      background: rgba(18,11,7,0.85);\n      border-bottom: 1px solid rgba(200,114,10,0.15);\n    }\n    .nav-logo {\n      font-family: 'Playfair Display', serif;\n      font-size: 22px; font-weight: 900; letter-spacing: 0.14em;\n      color: var(--gold); text-decoration: none; text-transform: uppercase;\n    }\n    .nav-links { display: flex; gap: 40px; list-style: none; }\n    .nav-links a {\n      font-family: 'DM Mono', monospace; font-size: 11px; font-weight: 400;\n      letter-spacing: 0.2em; text-transform: uppercase; text-decoration: none;\n      color: var(--fog); transition: color 0.3s;\n    }\n    .nav-links a:hover { color: var(--gold); }\n    .nav-cta {\n      font-family: 'DM Mono', monospace; font-size: 11px; letter-spacing: 0.18em;\n      text-transform: uppercase; text-decoration: none;\n      color: var(--espresso); background: var(--amber);\n      padding: 10px 22px; transition: background 0.3s, transform 0.2s;\n    }\n    .nav-cta:hover { background: var(--gold); transform: translateY(-1px); }\n\n    /* \u2500\u2500 Hero \u2500\u2500 */\n    .hero {\n      min-height: 100vh;\n      display: grid; grid-template-columns: 1fr 1fr;\n      position: relative; overflow: hidden;\n    }\n    .hero-bg {\n      position: absolute; inset: 0; z-index: 0;\n      background:\n        radial-gradient(ellipse 80% 60% at 60% 40%, rgba(200,114,10,0.18) 0%, transparent 70%),\n        radial-gradient(ellipse 60% 80% at 10% 90%, rgba(200,72,32,0.10) 0%, transparent 60%),\n        linear-gradient(135deg, #120b07 0%, #1e1008 40%, #2d1a0d 100%);\n    }\n    .hero-rings {\n      position: absolute; right: -60px; top: 50%; transform: translateY(-50%);\n      width: 620px; height: 620px; z-index: 1;\n    }\n    .hero-rings circle {\n      fill: none; stroke: rgba(200,114,10,0.12);\n      animation: rotateRing 20s linear infinite;\n      transform-origin: 310px 310px;\n    }\n    .hero-rings circle:nth-child(2) {\n      stroke: rgba(232,160,32,0.08);\n      animation-direction: reverse; animation-duration: 30s;\n    }\n    .hero-rings circle:nth-child(3) {\n      stroke: rgba(200,114,10,0.06);\n      animation-duration: 45s;\n    }\n    @keyframes rotateRing {\n      from { transform: rotate(0deg); }\n      to   { transform: rotate(360deg); }\n    }\n\n    .hero-left {\n      position: relative; z-index: 2;\n      display: flex; flex-direction: column; justify-content: center;\n      padding: 140px 56px 80px;\n    }\n    .hero-eyebrow {\n      font-family: 'DM Mono', monospace; font-size: 11px; font-weight: 400;\n      letter-spacing: 0.28em; text-transform: uppercase; color: var(--amber);\n      margin-bottom: 32px; opacity: 0;\n      animation: fadeUp 0.8s ease 0.3s forwards;\n    }\n    .hero-title {\n      font-family: 'Playfair Display', serif; font-weight: 900;\n      font-size: clamp(64px, 7vw, 110px); line-height: 0.9;\n      letter-spacing: -0.02em; color: var(--white);\n      margin-bottom: 12px;\n      opacity: 0; animation: fadeUp 0.9s ease 0.5s forwards;\n    }\n    .hero-title em {\n      font-style: italic; color: var(--gold);\n      display: block;\n    }\n    .hero-subtitle {\n      font-family: 'Playfair Display', serif; font-style: italic;\n      font-size: clamp(22px, 2.4vw, 34px); font-weight: 400;\n      color: var(--fog); margin-bottom: 48px;\n      opacity: 0; animation: fadeUp 0.9s ease 0.7s forwards;\n    }\n    .hero-desc {\n      font-family: 'Crimson Pro', serif; font-size: 17px; font-weight: 300;\n      line-height: 1.75; color: rgba(180,150,120,0.85); max-width: 420px;\n      margin-bottom: 52px;\n      opacity: 0; animation: fadeUp 0.9s ease 0.9s forwards;\n    }\n    .hero-actions {\n      display: flex; gap: 20px; align-items: center;\n      opacity: 0; animation: fadeUp 0.9s ease 1.1s forwards;\n    }\n    .btn-primary {\n      display: inline-block; text-decoration: none;\n      font-family: 'DM Mono', monospace; font-size: 12px; font-weight: 500;\n      letter-spacing: 0.18em; text-transform: uppercase;\n      color: var(--espresso); background: var(--amber);\n      padding: 16px 36px;\n      position: relative; overflow: hidden;\n      transition: color 0.3s, transform 0.2s;\n    }\n    .btn-primary::after {\n      content: ''; position: absolute; inset: 0;\n      background: var(--gold);\n      transform: translateX(-100%);\n      transition: transform 0.4s cubic-bezier(.16,1,.3,1);\n    }\n    .btn-primary:hover::after { transform: translateX(0); }\n    .btn-primary span { position: relative; z-index: 1; }\n    .btn-primary:hover { transform: translateY(-2px); }\n\n    .btn-ghost {\n      display: inline-flex; align-items: center; gap: 10px;\n      text-decoration: none;\n      font-family: 'DM Mono', monospace; font-size: 11px; font-weight: 400;\n      letter-spacing: 0.18em; text-transform: uppercase; color: var(--fog);\n      transition: color 0.3s;\n    }\n    .btn-ghost::before {\n      content: ''; display: block;\n      width: 32px; height: 1px; background: currentColor;\n      transition: width 0.3s;\n    }\n    .btn-ghost:hover { color: var(--cream); }\n    .btn-ghost:hover::before { width: 48px; }\n\n    .hero-right {\n      position: relative; z-index: 2;\n      display: flex; align-items: center; justify-content: center;\n      padding: 140px 56px 80px 0;\n    }\n    .hero-cup {\n      position: relative; width: 380px; height: 440px;\n      opacity: 0; animation: fadeIn 1.2s ease 0.8s forwards;\n    }\n    .cup-svg { width: 100%; height: 100%; }\n    .steam {\n      position: absolute; top: -60px; left: 50%; transform: translateX(-50%);\n      display: flex; gap: 20px;\n    }\n    .steam-line {\n      width: 2px; height: 60px;\n      background: linear-gradient(to top, rgba(200,114,10,0.4), transparent);\n      border-radius: 2px;\n      animation: steamRise 2.5s ease-in-out infinite;\n    }\n    .steam-line:nth-child(2) { animation-delay: 0.6s; height: 80px; }\n    .steam-line:nth-child(3) { animation-delay: 1.2s; }\n    @keyframes steamRise {\n      0%   { opacity: 0; transform: translateY(0) scaleX(1); }\n      30%  { opacity: 0.8; }\n      100% { opacity: 0; transform: translateY(-40px) scaleX(1.5); }\n    }\n\n    .hero-stats {\n      position: absolute; bottom: 60px; right: 56px;\n      display: flex; gap: 48px; z-index: 2;\n      opacity: 0; animation: fadeUp 0.9s ease 1.4s forwards;\n    }\n    .stat { text-align: right; }\n    .stat-num {\n      font-family: 'Playfair Display', serif; font-size: 42px; font-weight: 900;\n      color: var(--gold); line-height: 1;\n    }\n    .stat-label {\n      font-family: 'DM Mono', monospace; font-size: 10px;\n      letter-spacing: 0.2em; text-transform: uppercase; color: var(--fog);\n    }\n\n    /* \u2500\u2500 Ticker \u2500\u2500 */\n    .ticker {\n      background: var(--amber); overflow: hidden; padding: 14px 0;\n      border-top: 1px solid rgba(232,160,32,0.3);\n      border-bottom: 1px solid rgba(232,160,32,0.3);\n    }\n    .ticker-track {\n      display: flex; gap: 0; white-space: nowrap;\n      animation: ticker 30s linear infinite;\n    }\n    .ticker-item {\n      font-family: 'DM Mono', monospace; font-size: 11px; font-weight: 500;\n      letter-spacing: 0.2em; text-transform: uppercase; color: var(--espresso);\n      padding: 0 48px;\n      display: flex; align-items: center; gap: 16px;\n    }\n    .ticker-item::after {\n      content: '\u25c6'; font-size: 8px; opacity: 0.6;\n    }\n    @keyframes ticker { from { transform: translateX(0); } to { transform: translateX(-50%); } }\n\n    /* \u2500\u2500 Section base \u2500\u2500 */\n    section { position: relative; }\n    .section-label {\n      font-family: 'DM Mono', monospace; font-size: 10px; font-weight: 400;\n      letter-spacing: 0.32em; text-transform: uppercase; color: var(--amber);\n      margin-bottom: 20px;\n      display: flex; align-items: center; gap: 16px;\n    }\n    .section-label::before {\n      content: ''; display: block; width: 40px; height: 1px;\n      background: var(--amber);\n    }\n\n    /* \u2500\u2500 Origins \u2500\u2500 */\n    .origins {\n      padding: 120px 56px;\n      background: linear-gradient(180deg, var(--espresso) 0%, var(--roast) 100%);\n    }\n    .origins-header {\n      display: grid; grid-template-columns: 1fr 1fr; gap: 60px;\n      align-items: end; margin-bottom: 80px;\n    }\n    .origins-title {\n      font-family: 'Playfair Display', serif; font-weight: 900;\n      font-size: clamp(42px, 5vw, 72px); line-height: 0.95;\n      letter-spacing: -0.02em; color: var(--white);\n    }\n    .origins-title span { color: var(--gold); font-style: italic; }\n    .origins-body {\n      font-family: 'Crimson Pro', serif; font-size: 18px; font-weight: 300;\n      line-height: 1.8; color: var(--fog); max-width: 420px;\n    }\n    .origins-body strong { color: var(--cream); font-weight: 600; }\n\n    .origins-grid {\n      display: grid; grid-template-columns: repeat(3, 1fr); gap: 2px;\n    }\n    .origin-card {\n      position: relative; overflow: hidden; aspect-ratio: 3/4;\n      background: var(--bark);\n      cursor: none;\n    }\n    .origin-card:first-child { grid-row: span 2; aspect-ratio: auto; }\n    .origin-bg {\n      position: absolute; inset: 0;\n      transition: transform 0.8s cubic-bezier(.16,1,.3,1);\n    }\n    .origin-card:hover .origin-bg { transform: scale(1.06); }\n\n    /* coffee origin gradients */\n    .origin-card:nth-child(1) .origin-bg {\n      background:\n        radial-gradient(ellipse at 30% 60%, rgba(200,72,32,0.5) 0%, transparent 60%),\n        linear-gradient(160deg, #2d1a0d 0%, #1a3020 100%);\n    }\n    .origin-card:nth-child(2) .origin-bg {\n      background:\n        radial-gradient(ellipse at 70% 40%, rgba(200,114,10,0.5) 0%, transparent 60%),\n        linear-gradient(200deg, #1a1020 0%, #2d2008 100%);\n    }\n    .origin-card:nth-child(3) .origin-bg {\n      background:\n        radial-gradient(ellipse at 50% 70%, rgba(100,50,180,0.3) 0%, transparent 60%),\n        linear-gradient(40deg, #0d1820 0%, #201010 100%);\n    }\n    .origin-card:nth-child(4) .origin-bg {\n      background:\n        radial-gradient(ellipse at 30% 30%, rgba(60,140,80,0.3) 0%, transparent 60%),\n        linear-gradient(220deg, #0a1810 0%, #1e1008 100%);\n    }\n    .origin-card:nth-child(5) .origin-bg {\n      background:\n        radial-gradient(ellipse at 60% 50%, rgba(180,100,20,0.4) 0%, transparent 60%),\n        linear-gradient(100deg, #201008 0%, #0e1a0a 100%);\n    }\n\n    .origin-icon {\n      position: absolute; top: 28px; right: 28px;\n      font-size: 36px; opacity: 0.7;\n    }\n    .origin-content {\n      position: absolute; inset: 0; padding: 28px;\n      display: flex; flex-direction: column; justify-content: flex-end;\n      background: linear-gradient(to top, rgba(18,11,7,0.92) 0%, transparent 55%);\n    }\n    .origin-region {\n      font-family: 'DM Mono', monospace; font-size: 10px;\n      letter-spacing: 0.22em; text-transform: uppercase; color: var(--amber);\n      margin-bottom: 8px;\n    }\n    .origin-name {\n      font-family: 'Playfair Display', serif; font-size: 26px; font-weight: 700;\n      color: var(--white); line-height: 1.1; margin-bottom: 10px;\n    }\n    .origin-card:first-child .origin-name { font-size: 38px; }\n    .origin-notes {\n      font-family: 'Crimson Pro', serif; font-size: 14px; font-weight: 300;\n      color: var(--fog); line-height: 1.5;\n    }\n    .origin-altitude {\n      margin-top: 12px;\n      font-family: 'DM Mono', monospace; font-size: 10px;\n      letter-spacing: 0.18em; color: rgba(176,144,112,0.6);\n    }\n\n    /* \u2500\u2500 Featured Roasts \u2500\u2500 */\n    .roasts {\n      padding: 120px 56px;\n      background: var(--roast);\n    }\n    .roasts-header { margin-bottom: 72px; }\n    .roasts-title {\n      font-family: 'Playfair Display', serif; font-weight: 900;\n      font-size: clamp(42px, 5vw, 72px); line-height: 0.95;\n      letter-spacing: -0.02em; color: var(--white);\n      margin-bottom: 20px;\n    }\n    .roasts-title em { font-style: italic; color: var(--gold); }\n\n    .roasts-list { display: flex; flex-direction: column; }\n    .roast-item {\n      display: grid; grid-template-columns: 80px 1fr auto auto;\n      align-items: center; gap: 40px;\n      padding: 36px 0;\n      border-bottom: 1px solid rgba(255,255,255,0.06);\n      transition: background 0.3s, padding-left 0.3s;\n      cursor: none;\n    }\n    .roast-item:first-child { border-top: 1px solid rgba(255,255,255,0.06); }\n    .roast-item:hover { padding-left: 20px; background: rgba(200,114,10,0.04); }\n\n    .roast-num {\n      font-family: 'DM Mono', monospace; font-size: 11px; font-weight: 300;\n      color: rgba(176,144,112,0.4); letter-spacing: 0.12em;\n    }\n    .roast-info { }\n    .roast-name {\n      font-family: 'Playfair Display', serif; font-size: 28px; font-weight: 700;\n      color: var(--white); line-height: 1.1; margin-bottom: 8px;\n      transition: color 0.3s;\n    }\n    .roast-item:hover .roast-name { color: var(--gold); }\n    .roast-meta {\n      font-family: 'DM Mono', monospace; font-size: 10px; font-weight: 300;\n      letter-spacing: 0.18em; text-transform: uppercase; color: var(--fog);\n    }\n    .roast-flavor {\n      font-family: 'Crimson Pro', serif; font-size: 15px; font-style: italic;\n      color: rgba(176,144,112,0.6); text-align: right; max-width: 200px;\n    }\n    .roast-price {\n      font-family: 'Playfair Display', serif; font-size: 22px; font-weight: 700;\n      color: var(--amber); white-space: nowrap;\n    }\n    .roast-add {\n      display: flex; align-items: center; justify-content: center;\n      width: 44px; height: 44px; border-radius: 50%;\n      border: 1.5px solid rgba(200,114,10,0.4);\n      color: var(--amber); font-size: 22px; line-height: 1;\n      transition: background 0.3s, border-color 0.3s, transform 0.2s;\n      cursor: none;\n    }\n    .roast-item:hover .roast-add {\n      background: var(--amber); color: var(--espresso);\n      border-color: var(--amber); transform: rotate(45deg);\n    }\n\n    /* \u2500\u2500 Brew Methods \u2500\u2500 */\n    .brew {\n      padding: 120px 56px;\n      background: var(--espresso);\n      overflow: hidden;\n    }\n    .brew-inner {\n      display: grid; grid-template-columns: 400px 1fr; gap: 80px; align-items: center;\n    }\n    .brew-left { }\n    .brew-title {\n      font-family: 'Playfair Display', serif; font-weight: 900;\n      font-size: clamp(38px, 4.5vw, 62px); line-height: 0.95;\n      letter-spacing: -0.02em; color: var(--white); margin-bottom: 28px;\n    }\n    .brew-title em { font-style: italic; color: var(--gold); }\n    .brew-body {\n      font-family: 'Crimson Pro', serif; font-size: 18px; font-weight: 300;\n      line-height: 1.75; color: var(--fog); margin-bottom: 48px;\n    }\n    .brew-tabs {\n      display: flex; flex-direction: column; gap: 2px;\n    }\n    .brew-tab {\n      display: flex; align-items: center; gap: 20px;\n      padding: 18px 24px; cursor: none;\n      border-left: 2px solid transparent;\n      transition: border-color 0.3s, background 0.3s;\n    }\n    .brew-tab.active {\n      border-left-color: var(--amber);\n      background: rgba(200,114,10,0.08);\n    }\n    .brew-tab-icon { font-size: 22px; }\n    .brew-tab-name {\n      font-family: 'DM Mono', monospace; font-size: 12px; font-weight: 500;\n      letter-spacing: 0.16em; text-transform: uppercase;\n      color: var(--fog); transition: color 0.3s;\n    }\n    .brew-tab.active .brew-tab-name { color: var(--amber); }\n\n    .brew-right {\n      position: relative;\n    }\n    .brew-panel { display: none; }\n    .brew-panel.active { display: block; }\n    .brew-visual {\n      position: relative; height: 420px;\n      display: flex; align-items: center; justify-content: center;\n    }\n    .brew-diagram {\n      position: relative; z-index: 1;\n    }\n    .brew-glow {\n      position: absolute; inset: -40px;\n      background: radial-gradient(ellipse, rgba(200,114,10,0.2) 0%, transparent 70%);\n      border-radius: 50%;\n      animation: glowPulse 4s ease-in-out infinite;\n    }\n    @keyframes glowPulse {\n      0%, 100% { opacity: 0.6; transform: scale(1); }\n      50%       { opacity: 1;   transform: scale(1.08); }\n    }\n    .brew-steps {\n      display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px;\n      margin-top: 40px;\n    }\n    .brew-step {\n      padding: 24px;\n      background: rgba(255,255,255,0.03);\n      border: 1px solid rgba(255,255,255,0.06);\n    }\n    .step-num {\n      font-family: 'Playfair Display', serif; font-size: 42px; font-weight: 900;\n      color: rgba(200,114,10,0.25); line-height: 1; margin-bottom: 12px;\n    }\n    .step-title {\n      font-family: 'DM Mono', monospace; font-size: 11px; font-weight: 500;\n      letter-spacing: 0.18em; text-transform: uppercase; color: var(--cream);\n      margin-bottom: 8px;\n    }\n    .step-desc {\n      font-family: 'Crimson Pro', serif; font-size: 15px; font-weight: 300;\n      color: var(--fog); line-height: 1.6;\n    }\n\n    /* \u2500\u2500 Manifesto \u2500\u2500 */\n    .manifesto {\n      padding: 160px 56px;\n      background: var(--bark);\n      text-align: center;\n      position: relative; overflow: hidden;\n    }\n    .manifesto::before {\n      content: '\"';\n      position: absolute; top: -60px; left: 50%; transform: translateX(-50%);\n      font-family: 'Playfair Display', serif; font-size: 400px; font-weight: 900;\n      color: rgba(200,114,10,0.05); line-height: 1;\n      pointer-events: none;\n    }\n    .manifesto-quote {\n      font-family: 'Playfair Display', serif; font-style: italic;\n      font-size: clamp(28px, 4vw, 54px); font-weight: 400;\n      color: var(--cream); line-height: 1.3;\n      max-width: 900px; margin: 0 auto 40px; position: relative;\n    }\n    .manifesto-quote em { color: var(--gold); }\n    .manifesto-attr {\n      font-family: 'DM Mono', monospace; font-size: 11px; font-weight: 300;\n      letter-spacing: 0.24em; text-transform: uppercase; color: var(--fog);\n    }\n\n    /* \u2500\u2500 Newsletter \u2500\u2500 */\n    .newsletter {\n      padding: 120px 56px;\n      background: linear-gradient(135deg, var(--roast) 0%, var(--espresso) 100%);\n    }\n    .newsletter-inner {\n      max-width: 700px; margin: 0 auto; text-align: center;\n    }\n    .newsletter-title {\n      font-family: 'Playfair Display', serif; font-weight: 900;\n      font-size: clamp(36px, 4.5vw, 60px); line-height: 1;\n      color: var(--white); margin-bottom: 20px; letter-spacing: -0.02em;\n    }\n    .newsletter-title em { font-style: italic; color: var(--gold); }\n    .newsletter-sub {\n      font-family: 'Crimson Pro', serif; font-size: 18px; font-weight: 300;\n      color: var(--fog); line-height: 1.7; margin-bottom: 52px;\n    }\n    .newsletter-form {\n      display: flex; gap: 0; max-width: 520px; margin: 0 auto;\n    }\n    .newsletter-input {\n      flex: 1; padding: 18px 24px;\n      background: rgba(255,255,255,0.06);\n      border: 1.5px solid rgba(200,114,10,0.3);\n      border-right: none;\n      color: var(--cream);\n      font-family: 'Crimson Pro', serif; font-size: 17px;\n      outline: none;\n      transition: border-color 0.3s;\n    }\n    .newsletter-input::placeholder { color: var(--fog); }\n    .newsletter-input:focus { border-color: var(--amber); }\n    .newsletter-btn {\n      padding: 18px 32px;\n      background: var(--amber); color: var(--espresso);\n      border: none;\n      font-family: 'DM Mono', monospace; font-size: 11px; font-weight: 500;\n      letter-spacing: 0.2em; text-transform: uppercase;\n      cursor: none; transition: background 0.3s;\n    }\n    .newsletter-btn:hover { background: var(--gold); }\n\n    /* \u2500\u2500 Footer \u2500\u2500 */\n    footer {\n      padding: 80px 56px 48px;\n      background: #0c0704;\n      border-top: 1px solid rgba(200,114,10,0.12);\n    }\n    .footer-top {\n      display: grid; grid-template-columns: 280px 1fr 1fr 1fr;\n      gap: 60px; margin-bottom: 64px;\n    }\n    .footer-brand { }\n    .footer-logo {\n      font-family: 'Playfair Display', serif; font-size: 24px; font-weight: 900;\n      letter-spacing: 0.12em; text-transform: uppercase; color: var(--gold);\n      display: block; margin-bottom: 20px;\n    }\n    .footer-tagline {\n      font-family: 'Crimson Pro', serif; font-size: 16px; font-weight: 300;\n      font-style: italic; color: var(--fog); line-height: 1.6;\n    }\n    .footer-col h4 {\n      font-family: 'DM Mono', monospace; font-size: 10px; font-weight: 500;\n      letter-spacing: 0.26em; text-transform: uppercase; color: var(--amber);\n      margin-bottom: 24px;\n    }\n    .footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 12px; }\n    .footer-col a {\n      font-family: 'Crimson Pro', serif; font-size: 16px; font-weight: 300;\n      color: var(--fog); text-decoration: none; transition: color 0.3s;\n    }\n    .footer-col a:hover { color: var(--cream); }\n    .footer-bottom {\n      display: flex; justify-content: space-between; align-items: center;\n      padding-top: 32px; border-top: 1px solid rgba(255,255,255,0.06);\n    }\n    .footer-copy {\n      font-family: 'DM Mono', monospace; font-size: 10px; font-weight: 300;\n      letter-spacing: 0.16em; text-transform: uppercase; color: rgba(176,144,112,0.4);\n    }\n    .footer-socials { display: flex; gap: 20px; }\n    .footer-socials a {\n      font-family: 'DM Mono', monospace; font-size: 10px; font-weight: 400;\n      letter-spacing: 0.18em; text-transform: uppercase;\n      color: rgba(176,144,112,0.4); text-decoration: none; transition: color 0.3s;\n    }\n    .footer-socials a:hover { color: var(--amber); }\n\n    /* \u2500\u2500 Scroll reveal \u2500\u2500 */\n    .reveal {\n      opacity: 0; transform: translateY(32px);\n      transition: opacity 0.8s cubic-bezier(.16,1,.3,1), transform 0.8s cubic-bezier(.16,1,.3,1);\n    }\n    .reveal.visible { opacity: 1; transform: translateY(0); }\n    .reveal-delay-1 { transition-delay: 0.1s; }\n    .reveal-delay-2 { transition-delay: 0.2s; }\n    .reveal-delay-3 { transition-delay: 0.35s; }\n    .reveal-delay-4 { transition-delay: 0.5s; }\n\n    @keyframes fadeUp {\n      from { opacity: 0; transform: translateY(28px); }\n      to   { opacity: 1; transform: translateY(0); }\n    }\n    @keyframes fadeIn {\n      from { opacity: 0; }\n      to   { opacity: 1; }\n    }\n\n    /* \u2500\u2500 Responsive \u2500\u2500 */\n    @media (max-width: 900px) {\n      nav { padding: 20px 24px; }\n      .nav-links { display: none; }\n      .hero { grid-template-columns: 1fr; }\n      .hero-right { display: none; }\n      .hero-left { padding: 120px 24px 80px; }\n      .hero-stats { right: 24px; gap: 24px; }\n      .origins { padding: 80px 24px; }\n      .origins-header { grid-template-columns: 1fr; gap: 30px; }\n      .origins-grid { grid-template-columns: 1fr 1fr; }\n      .origins-grid .origin-card:first-child { grid-row: span 1; }\n      .roasts { padding: 80px 24px; }\n      .roast-item { grid-template-columns: 1fr auto; gap: 16px; }\n      .roast-num, .roast-flavor { display: none; }\n      .brew { padding: 80px 24px; }\n      .brew-inner { grid-template-columns: 1fr; }\n      .manifesto { padding: 100px 24px; }\n      .newsletter { padding: 80px 24px; }\n      .newsletter-form { flex-direction: column; }\n      .newsletter-input { border-right: 1.5px solid rgba(200,114,10,0.3); }\n      footer { padding: 60px 24px 40px; }\n      .footer-top { grid-template-columns: 1fr 1fr; }\n    }\n  </style>\n</head>\n<body>\n\n  <!-- Custom cursor -->\n  <div class=\"cursor\"><div class=\"cursor-dot\" id=\"cursorDot\"></div></div>\n  <div class=\"cursor-ring\" id=\"cursorRing\"></div>\n\n  <!-- Nav -->\n  <nav id=\"nav\">\n    <a href=\"#\" class=\"nav-logo\">Terroir</a>\n    <ul class=\"nav-links\">\n      <li><a href=\"#origins\">Origins</a></li>\n      <li><a href=\"#roasts\">Roasts</a></li>\n      <li><a href=\"#brew\">Brew</a></li>\n      <li><a href=\"#about\">About</a></li>\n    </ul>\n    <a href=\"#roasts\" class=\"nav-cta\">Shop Now</a>\n  </nav>\n\n  <!-- Hero -->\n  <section class=\"hero\">\n    <div class=\"hero-bg\"></div>\n    <svg class=\"hero-rings\" viewBox=\"0 0 620 620\" xmlns=\"http://www.w3.org/2000/svg\" aria-hidden=\"true\">\n      <circle cx=\"310\" cy=\"310\" r=\"280\" stroke-width=\"1\" stroke-dasharray=\"12 8\"/>\n      <circle cx=\"310\" cy=\"310\" r=\"220\" stroke-width=\"1\" stroke-dasharray=\"4 12\"/>\n      <circle cx=\"310\" cy=\"310\" r=\"160\" stroke-width=\"0.5\"/>\n    </svg>\n\n    <div class=\"hero-left\">\n      <div class=\"hero-eyebrow\">Single Origin \u00b7 Micro-Roasted \u00b7 Direct Trade</div>\n      <h1 class=\"hero-title\">\n        The Art<br/>of the<br/><em>Perfect Cup</em>\n      </h1>\n      <p class=\"hero-subtitle\">Where soil becomes soul.</p>\n      <p class=\"hero-desc\">\n        Every harvest tells a story of altitude, rainfall, and the hands that tended it.\n        We source directly from 47 farms across 12 countries, roasting in micro-batches\n        to honor every nuance the land has to offer.\n      </p>\n      <div class=\"hero-actions\">\n        <a href=\"#roasts\" class=\"btn-primary\"><span>Explore Roasts</span></a>\n        <a href=\"#origins\" class=\"btn-ghost\">Our Origins</a>\n      </div>\n    </div>\n\n    <div class=\"hero-right\">\n      <div class=\"hero-cup\">\n        <div class=\"steam\">\n          <div class=\"steam-line\"></div>\n          <div class=\"steam-line\"></div>\n          <div class=\"steam-line\"></div>\n        </div>\n        <svg class=\"cup-svg\" viewBox=\"0 0 380 440\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n          <!-- Saucer -->\n          <ellipse cx=\"190\" cy=\"390\" rx=\"160\" ry=\"22\" fill=\"url(#saucerGrad)\" opacity=\"0.9\"/>\n          <ellipse cx=\"190\" cy=\"388\" rx=\"148\" ry=\"16\" fill=\"url(#saucerTop)\"/>\n          <!-- Cup body -->\n          <path d=\"M 80 200 Q 75 340 100 370 Q 190 390 280 370 Q 305 340 300 200 Z\"\n                fill=\"url(#cupBody)\"/>\n          <!-- Cup inner dark -->\n          <ellipse cx=\"190\" cy=\"200\" rx=\"110\" ry=\"28\" fill=\"url(#coffeeTop)\"/>\n          <!-- Coffee surface -->\n          <ellipse cx=\"190\" cy=\"200\" rx=\"102\" ry=\"24\" fill=\"url(#coffeeSurface)\"/>\n          <!-- Crema swirl -->\n          <ellipse cx=\"190\" cy=\"198\" rx=\"70\" ry=\"14\" fill=\"none\"\n                   stroke=\"url(#cremaStroke)\" stroke-width=\"2\" opacity=\"0.6\"\n                   stroke-dasharray=\"6 4\"/>\n          <ellipse cx=\"190\" cy=\"198\" rx=\"40\" ry=\"8\" fill=\"none\"\n                   stroke=\"url(#cremaStroke)\" stroke-width=\"1.5\" opacity=\"0.4\"/>\n          <!-- Cup highlight -->\n          <path d=\"M 92 220 Q 88 300 100 355\" stroke=\"rgba(255,255,255,0.08)\" stroke-width=\"3\" stroke-linecap=\"round\"/>\n          <!-- Handle -->\n          <path d=\"M 295 240 Q 355 240 355 290 Q 355 340 295 340\"\n                stroke=\"url(#handleGrad)\" stroke-width=\"14\" fill=\"none\" stroke-linecap=\"round\"/>\n          <path d=\"M 295 240 Q 345 240 345 290 Q 345 330 295 340\"\n                stroke=\"url(#handleInner)\" stroke-width=\"6\" fill=\"none\" stroke-linecap=\"round\" opacity=\"0.5\"/>\n          <!-- Decorative ring -->\n          <ellipse cx=\"190\" cy=\"200\" rx=\"110\" ry=\"28\" fill=\"none\"\n                   stroke=\"rgba(200,114,10,0.25)\" stroke-width=\"1.5\"/>\n          <!-- Cup rim -->\n          <ellipse cx=\"190\" cy=\"198\" rx=\"112\" ry=\"30\" fill=\"url(#rimGrad)\"/>\n          <!-- Logo on cup -->\n          <text x=\"190\" y=\"300\" text-anchor=\"middle\"\n                font-family=\"serif\" font-size=\"14\" letter-spacing=\"6\"\n                fill=\"rgba(200,114,10,0.35)\" text-decoration=\"none\">TERROIR</text>\n\n          <defs>\n            <linearGradient id=\"cupBody\" x1=\"80\" y1=\"200\" x2=\"300\" y2=\"380\" gradientUnits=\"userSpaceOnUse\">\n              <stop offset=\"0%\" stop-color=\"#4a2412\"/>\n              <stop offset=\"50%\" stop-color=\"#3a1c0e\"/>\n              <stop offset=\"100%\" stop-color=\"#2d1a0d\"/>\n            </linearGradient>\n            <radialGradient id=\"coffeeSurface\" cx=\"40%\" cy=\"40%\" r=\"60%\">\n              <stop offset=\"0%\" stop-color=\"#8b4a1a\"/>\n              <stop offset=\"50%\" stop-color=\"#5a2e10\"/>\n              <stop offset=\"100%\" stop-color=\"#3a1c0a\"/>\n            </radialGradient>\n            <radialGradient id=\"coffeeTop\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n              <stop offset=\"0%\" stop-color=\"#2d1a0d\"/>\n              <stop offset=\"100%\" stop-color=\"#1e1008\"/>\n            </radialGradient>\n            <linearGradient id=\"saucerGrad\" x1=\"30\" y1=\"370\" x2=\"350\" y2=\"410\" gradientUnits=\"userSpaceOnUse\">\n              <stop offset=\"0%\" stop-color=\"#2d1a0d\"/>\n              <stop offset=\"100%\" stop-color=\"#1e1008\"/>\n            </linearGradient>\n            <linearGradient id=\"saucerTop\" x1=\"42\" y1=\"372\" x2=\"338\" y2=\"405\" gradientUnits=\"userSpaceOnUse\">\n              <stop offset=\"0%\" stop-color=\"#3a2010\"/>\n              <stop offset=\"50%\" stop-color=\"#4a2816\"/>\n              <stop offset=\"100%\" stop-color=\"#2d1a0d\"/>\n            </linearGradient>\n            <linearGradient id=\"handleGrad\" x1=\"295\" y1=\"240\" x2=\"355\" y2=\"340\" gradientUnits=\"userSpaceOnUse\">\n              <stop offset=\"0%\" stop-color=\"#4a2412\"/>\n              <stop offset=\"100%\" stop-color=\"#2d1a0d\"/>\n            </linearGradient>\n            <linearGradient id=\"handleInner\" x1=\"295\" y1=\"240\" x2=\"345\" y2=\"340\" gradientUnits=\"userSpaceOnUse\">\n              <stop offset=\"0%\" stop-color=\"rgba(255,255,255,0.12)\"/>\n              <stop offset=\"100%\" stop-color=\"rgba(255,255,255,0.02)\"/>\n            </linearGradient>\n            <linearGradient id=\"rimGrad\" x1=\"78\" y1=\"168\" x2=\"302\" y2=\"228\" gradientUnits=\"userSpaceOnUse\">\n              <stop offset=\"0%\" stop-color=\"#6a3820\" stop-opacity=\"0.9\"/>\n              <stop offset=\"50%\" stop-color=\"#4a2412\" stop-opacity=\"0.7\"/>\n              <stop offset=\"100%\" stop-color=\"#2d1a0d\" stop-opacity=\"0.9\"/>\n            </linearGradient>\n            <linearGradient id=\"cremaStroke\" x1=\"120\" y1=\"184\" x2=\"260\" y2=\"212\" gradientUnits=\"userSpaceOnUse\">\n              <stop offset=\"0%\" stop-color=\"#c87220\"/>\n              <stop offset=\"100%\" stop-color=\"#e8a020\"/>\n            </linearGradient>\n          </defs>\n        </svg>\n      </div>\n    </div>\n\n    <div class=\"hero-stats\">\n      <div class=\"stat\">\n        <div class=\"stat-num\">47</div>\n        <div class=\"stat-label\">Partner Farms</div>\n      </div>\n      <div class=\"stat\">\n        <div class=\"stat-num\">12</div>\n        <div class=\"stat-label\">Countries</div>\n      </div>\n      <div class=\"stat\">\n        <div class=\"stat-num\">98\u00b0</div>\n        <div class=\"stat-label\">Bloom Temp</div>\n      </div>\n    </div>\n  </section>\n\n  <!-- Ticker -->\n  <div class=\"ticker\" aria-hidden=\"true\">\n    <div class=\"ticker-track\">\n      <span class=\"ticker-item\">Ethiopia Yirgacheffe</span>\n      <span class=\"ticker-item\">Colombia Huila</span>\n      <span class=\"ticker-item\">Kenya AA Nyeri</span>\n      <span class=\"ticker-item\">Guatemala Antigua</span>\n      <span class=\"ticker-item\">Yemen Haraaz</span>\n      <span class=\"ticker-item\">Panama Geisha</span>\n      <span class=\"ticker-item\">Indonesia Sumatra</span>\n      <span class=\"ticker-item\">Brazil Cerrado</span>\n      <span class=\"ticker-item\">Ethiopia Yirgacheffe</span>\n      <span class=\"ticker-item\">Colombia Huila</span>\n      <span class=\"ticker-item\">Kenya AA Nyeri</span>\n      <span class=\"ticker-item\">Guatemala Antigua</span>\n      <span class=\"ticker-item\">Yemen Haraaz</span>\n      <span class=\"ticker-item\">Panama Geisha</span>\n      <span class=\"ticker-item\">Indonesia Sumatra</span>\n      <span class=\"ticker-item\">Brazil Cerrado</span>\n    </div>\n  </div>\n\n  <!-- Origins -->\n  <section class=\"origins\" id=\"origins\">\n    <div class=\"origins-header\">\n      <div>\n        <div class=\"section-label reveal\">The Farms</div>\n        <h2 class=\"origins-title reveal reveal-delay-1\">\n          Rooted in<br/><span>Extraordinary</span><br/>Terroir\n        </h2>\n      </div>\n      <div>\n        <p class=\"origins-body reveal reveal-delay-2\">\n          <strong>Terroir</strong> is not just a wine concept. The volcanic soil of Ethiopia,\n          the high-altitude winds of Colombia, the ancient forests of Yemen \u2014\n          these are the invisible ingredients in every cup we roast.\n        </p>\n      </div>\n    </div>\n\n    <div class=\"origins-grid reveal\">\n      <div class=\"origin-card\">\n        <div class=\"origin-bg\"></div>\n        <div class=\"origin-icon\">\ud83c\udf3f</div>\n        <div class=\"origin-content\">\n          <div class=\"origin-region\">East Africa</div>\n          <div class=\"origin-name\">Ethiopia<br/>Yirgacheffe</div>\n          <div class=\"origin-notes\">Jasmine, bergamot, lemon curd \u00b7 Natural process \u00b7 Grade 1</div>\n          <div class=\"origin-altitude\">\u25b2 1,800\u20132,200 masl</div>\n        </div>\n      </div>\n      <div class=\"origin-card\">\n        <div class=\"origin-bg\"></div>\n        <div class=\"origin-icon\">\u26f0\ufe0f</div>\n        <div class=\"origin-content\">\n          <div class=\"origin-region\">South America</div>\n          <div class=\"origin-name\">Colombia<br/>Huila</div>\n          <div class=\"origin-notes\">Red apple, panela, dark chocolate \u00b7 Washed</div>\n          <div class=\"origin-altitude\">\u25b2 1,600\u20131,900 masl</div>\n        </div>\n      </div>\n      <div class=\"origin-card\">\n        <div class=\"origin-bg\"></div>\n        <div class=\"origin-icon\">\u2728</div>\n        <div class=\"origin-content\">\n          <div class=\"origin-region\">Central America</div>\n          <div class=\"origin-name\">Panama<br/>Geisha</div>\n          <div class=\"origin-notes\">Rose, tropical fruit, tea-like body \u00b7 Natural</div>\n          <div class=\"origin-altitude\">\u25b2 1,500\u20131,700 masl</div>\n        </div>\n      </div>\n      <div class=\"origin-card\">\n        <div class=\"origin-bg\"></div>\n        <div class=\"origin-icon\">\ud83c\udf31</div>\n        <div class=\"origin-content\">\n          <div class=\"origin-region\">East Africa</div>\n          <div class=\"origin-name\">Kenya<br/>Nyeri AA</div>\n          <div class=\"origin-notes\">Blackcurrant, tomato, wine \u00b7 Double-washed</div>\n          <div class=\"origin-altitude\">\u25b2 1,700\u20132,100 masl</div>\n        </div>\n      </div>\n      <div class=\"origin-card\">\n        <div class=\"origin-bg\"></div>\n        <div class=\"origin-icon\">\ud83c\udfd4\ufe0f</div>\n        <div class=\"origin-content\">\n          <div class=\"origin-region\">Middle East</div>\n          <div class=\"origin-name\">Yemen<br/>Haraaz</div>\n          <div class=\"origin-notes\">Dark fruit, cardamom, aged wood \u00b7 Dry process</div>\n          <div class=\"origin-altitude\">\u25b2 1,400\u20132,000 masl</div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- Roasts -->\n  <section class=\"roasts\" id=\"roasts\">\n    <div class=\"roasts-header\">\n      <div class=\"section-label reveal\">Current Offerings</div>\n      <h2 class=\"roasts-title reveal reveal-delay-1\">\n        This Season's<br/><em>Finest Roasts</em>\n      </h2>\n    </div>\n\n    <div class=\"roasts-list\">\n      <div class=\"roast-item reveal\">\n        <div class=\"roast-num\">01</div>\n        <div class=\"roast-info\">\n          <div class=\"roast-name\">Morning Rites Blend</div>\n          <div class=\"roast-meta\">Medium Roast \u00b7 Brazil + Colombia \u00b7 250g</div>\n        </div>\n        <div class=\"roast-flavor\">Milk chocolate, hazelnuts, brown sugar</div>\n        <div class=\"roast-price\">$24</div>\n        <div class=\"roast-add\">+</div>\n      </div>\n      <div class=\"roast-item reveal reveal-delay-1\">\n        <div class=\"roast-num\">02</div>\n        <div class=\"roast-info\">\n          <div class=\"roast-name\">Yirgacheffe Natural</div>\n          <div class=\"roast-meta\">Light Roast \u00b7 Ethiopia \u00b7 Single Origin \u00b7 200g</div>\n        </div>\n        <div class=\"roast-flavor\">Jasmine blossom, blueberry, lemon zest</div>\n        <div class=\"roast-price\">$32</div>\n        <div class=\"roast-add\">+</div>\n      </div>\n      <div class=\"roast-item reveal reveal-delay-2\">\n        <div class=\"roast-num\">03</div>\n        <div class=\"roast-info\">\n          <div class=\"roast-name\">Panama Geisha Reserve</div>\n          <div class=\"roast-meta\">Light Roast \u00b7 Panama \u00b7 Micro-lot \u00b7 150g</div>\n        </div>\n        <div class=\"roast-flavor\">Tropical florals, white peach, bergamot tea</div>\n        <div class=\"roast-price\">$68</div>\n        <div class=\"roast-add\">+</div>\n      </div>\n      <div class=\"roast-item reveal reveal-delay-3\">\n        <div class=\"roast-num\">04</div>\n        <div class=\"roast-info\">\n          <div class=\"roast-name\">Dark Altar Espresso</div>\n          <div class=\"roast-meta\">Dark Roast \u00b7 Multi-Origin \u00b7 Espresso Blend \u00b7 250g</div>\n        </div>\n        <div class=\"roast-flavor\">Bittersweet cacao, clove, smoked caramel</div>\n        <div class=\"roast-price\">$28</div>\n        <div class=\"roast-add\">+</div>\n      </div>\n      <div class=\"roast-item reveal reveal-delay-4\">\n        <div class=\"roast-num\">05</div>\n        <div class=\"roast-info\">\n          <div class=\"roast-name\">Yemen Haraaz Wild</div>\n          <div class=\"roast-meta\">Medium-Dark \u00b7 Yemen \u00b7 Heritage Lot \u00b7 200g</div>\n        </div>\n        <div class=\"roast-flavor\">Dried fig, cardamom, ancient earth</div>\n        <div class=\"roast-price\">$44</div>\n        <div class=\"roast-add\">+</div>\n      </div>\n    </div>\n  </section>\n\n  <!-- Brew Methods -->\n  <section class=\"brew\" id=\"brew\">\n    <div class=\"brew-inner\">\n      <div class=\"brew-left\">\n        <div class=\"section-label reveal\">The Ritual</div>\n        <h2 class=\"brew-title reveal reveal-delay-1\">\n          Brew With<br/><em>Intention</em>\n        </h2>\n        <p class=\"brew-body reveal reveal-delay-2\">\n          Great coffee is a practice. Each method extracts differently \u2014\n          revealing hidden layers or drawing out body and sweetness.\n          Choose your ritual.\n        </p>\n        <div class=\"brew-tabs reveal reveal-delay-3\">\n          <div class=\"brew-tab active\" data-panel=\"pourover\">\n            <div class=\"brew-tab-icon\">\u2615</div>\n            <div class=\"brew-tab-name\">Pour Over</div>\n          </div>\n          <div class=\"brew-tab\" data-panel=\"aeropress\">\n            <div class=\"brew-tab-icon\">\ud83e\uddea</div>\n            <div class=\"brew-tab-name\">AeroPress</div>\n          </div>\n          <div class=\"brew-tab\" data-panel=\"espresso\">\n            <div class=\"brew-tab-icon\">\u26a1</div>\n            <div class=\"brew-tab-name\">Espresso</div>\n          </div>\n          <div class=\"brew-tab\" data-panel=\"coldbrew\">\n            <div class=\"brew-tab-icon\">\ud83e\uddca</div>\n            <div class=\"brew-tab-name\">Cold Brew</div>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"brew-right\">\n        <!-- Pour Over -->\n        <div class=\"brew-panel active\" id=\"panel-pourover\">\n          <div class=\"brew-visual\">\n            <div class=\"brew-glow\"></div>\n            <div class=\"brew-diagram\">\n              <svg width=\"200\" height=\"280\" viewBox=\"0 0 200 280\" fill=\"none\">\n                <!-- Dripper -->\n                <path d=\"M 50 40 L 30 180 Q 30 200 100 200 Q 170 200 170 180 L 150 40 Z\"\n                      fill=\"url(#drip1)\" stroke=\"rgba(200,114,10,0.3)\" stroke-width=\"1\"/>\n                <!-- Coffee inside dripper -->\n                <path d=\"M 60 60 L 48 160 Q 48 180 100 180 Q 152 180 152 160 L 140 60 Z\"\n                      fill=\"url(#coffee1)\" opacity=\"0.8\"/>\n                <!-- Filter lines -->\n                <line x1=\"65\" y1=\"80\" x2=\"68\" y2=\"165\" stroke=\"rgba(200,114,10,0.15)\" stroke-width=\"1\"/>\n                <line x1=\"100\" y1=\"55\" x2=\"100\" y2=\"170\" stroke=\"rgba(200,114,10,0.15)\" stroke-width=\"1\"/>\n                <line x1=\"135\" y1=\"80\" x2=\"132\" y2=\"165\" stroke=\"rgba(200,114,10,0.15)\" stroke-width=\"1\"/>\n                <!-- Drip -->\n                <ellipse cx=\"100\" cy=\"205\" rx=\"4\" ry=\"8\" fill=\"url(#drip1)\" opacity=\"0.8\"/>\n                <!-- Server below -->\n                <rect x=\"60\" y=\"220\" width=\"80\" height=\"50\" rx=\"4\" fill=\"url(#server1)\" stroke=\"rgba(200,114,10,0.2)\" stroke-width=\"1\"/>\n                <!-- Coffee in server -->\n                <rect x=\"62\" y=\"250\" width=\"76\" height=\"18\" rx=\"2\" fill=\"url(#coffee1)\" opacity=\"0.6\"/>\n                <!-- Water pour (animated) -->\n                <path d=\"M 90 0 Q 95 20 100 40\" stroke=\"url(#water1)\" stroke-width=\"3\" stroke-linecap=\"round\"\n                      stroke-dasharray=\"4 4\" opacity=\"0.6\">\n                  <animate attributeName=\"stroke-dashoffset\" from=\"0\" to=\"16\" dur=\"1s\" repeatCount=\"indefinite\"/>\n                </path>\n                <defs>\n                  <linearGradient id=\"drip1\" x1=\"50\" y1=\"40\" x2=\"170\" y2=\"200\" gradientUnits=\"userSpaceOnUse\">\n                    <stop offset=\"0%\" stop-color=\"#4a2412\"/>\n                    <stop offset=\"100%\" stop-color=\"#2d1a0d\"/>\n                  </linearGradient>\n                  <linearGradient id=\"coffee1\" x1=\"60\" y1=\"55\" x2=\"150\" y2=\"180\" gradientUnits=\"userSpaceOnUse\">\n                    <stop offset=\"0%\" stop-color=\"#8b4a1a\"/>\n                    <stop offset=\"100%\" stop-color=\"#4a2412\"/>\n                  </linearGradient>\n                  <linearGradient id=\"server1\" x1=\"60\" y1=\"220\" x2=\"140\" y2=\"270\" gradientUnits=\"userSpaceOnUse\">\n                    <stop offset=\"0%\" stop-color=\"#3a2010\"/>\n                    <stop offset=\"100%\" stop-color=\"#2d1a0d\"/>\n                  </linearGradient>\n                  <linearGradient id=\"water1\" x1=\"90\" y1=\"0\" x2=\"100\" y2=\"40\" gradientUnits=\"userSpaceOnUse\">\n                    <stop offset=\"0%\" stop-color=\"rgba(200,114,10,0)\"/>\n                    <stop offset=\"100%\" stop-color=\"#c87210\"/>\n                  </linearGradient>\n                </defs>\n              </svg>\n            </div>\n          </div>\n          <div class=\"brew-steps\">\n            <div class=\"brew-step\">\n              <div class=\"step-num\">01</div>\n              <div class=\"step-title\">Bloom</div>\n              <div class=\"step-desc\">30g water \u00b7 45s \u00b7 Pre-infuse grounds to release CO\u2082</div>\n            </div>\n            <div class=\"brew-step\">\n              <div class=\"step-num\">02</div>\n              <div class=\"step-title\">Pour</div>\n              <div class=\"step-desc\">Spiral pours \u00b7 200g total \u00b7 3:00 min draw-down</div>\n            </div>\n            <div class=\"brew-step\">\n              <div class=\"step-num\">03</div>\n              <div class=\"step-title\">Ratio</div>\n              <div class=\"step-desc\">1:15 coffee to water \u00b7 Grind medium-coarse</div>\n            </div>\n          </div>\n        </div>\n\n        <!-- AeroPress -->\n        <div class=\"brew-panel\" id=\"panel-aeropress\">\n          <div class=\"brew-visual\">\n            <div class=\"brew-glow\"></div>\n            <div class=\"brew-diagram\">\n              <svg width=\"200\" height=\"280\" viewBox=\"0 0 200 280\" fill=\"none\">\n                <!-- Chamber -->\n                <rect x=\"70\" y=\"60\" width=\"60\" height=\"160\" rx=\"4\"\n                      fill=\"url(#ap1)\" stroke=\"rgba(200,114,10,0.25)\" stroke-width=\"1\"/>\n                <!-- Plunger -->\n                <rect x=\"75\" y=\"55\" width=\"50\" height=\"12\" rx=\"2\" fill=\"url(#ap2)\"/>\n                <rect x=\"90\" y=\"20\" width=\"20\" height=\"40\" rx=\"2\" fill=\"url(#ap2)\"/>\n                <!-- Coffee inside -->\n                <rect x=\"72\" y=\"180\" width=\"56\" height=\"36\" rx=\"2\" fill=\"url(#coffee2)\" opacity=\"0.8\"/>\n                <!-- Filter cap -->\n                <rect x=\"68\" y=\"218\" width=\"64\" height=\"8\" rx=\"3\" fill=\"#3a2010\" stroke=\"rgba(200,114,10,0.3)\" stroke-width=\"1\"/>\n                <!-- Spout drips -->\n                <ellipse cx=\"100\" cy=\"240\" rx=\"3\" ry=\"6\" fill=\"#8b4a1a\" opacity=\"0.7\"/>\n                <defs>\n                  <linearGradient id=\"ap1\" x1=\"70\" y1=\"60\" x2=\"130\" y2=\"220\" gradientUnits=\"userSpaceOnUse\">\n                    <stop offset=\"0%\" stop-color=\"#4a2412\" stop-opacity=\"0.4\"/>\n                    <stop offset=\"100%\" stop-color=\"#2d1a0d\" stop-opacity=\"0.6\"/>\n                  </linearGradient>\n                  <linearGradient id=\"ap2\" x1=\"75\" y1=\"20\" x2=\"125\" y2=\"70\" gradientUnits=\"userSpaceOnUse\">\n                    <stop offset=\"0%\" stop-color=\"#5a3020\"/>\n                    <stop offset=\"100%\" stop-color=\"#3a1c0e\"/>\n                  </linearGradient>\n                  <linearGradient id=\"coffee2\" x1=\"72\" y1=\"180\" x2=\"128\" y2=\"216\" gradientUnits=\"userSpaceOnUse\">\n                    <stop offset=\"0%\" stop-color=\"#8b4a1a\"/>\n                    <stop offset=\"100%\" stop-color=\"#4a2412\"/>\n                  </linearGradient>\n                </defs>\n              </svg>\n            </div>\n          </div>\n          <div class=\"brew-steps\">\n            <div class=\"brew-step\">\n              <div class=\"step-num\">01</div>\n              <div class=\"step-title\">Steep</div>\n              <div class=\"step-desc\">17g coffee \u00b7 250ml at 85\u00b0C \u00b7 Stir 10s \u00b7 Cap</div>\n            </div>\n            <div class=\"brew-step\">\n              <div class=\"step-num\">02</div>\n              <div class=\"step-title\">Wait</div>\n              <div class=\"step-desc\">Inverted method \u00b7 1:30 steep for clarity</div>\n            </div>\n            <div class=\"brew-step\">\n              <div class=\"step-num\">03</div>\n              <div class=\"step-title\">Press</div>\n              <div class=\"step-desc\">Slow 30s press \u00b7 Stop at hiss \u00b7 Total 2:00</div>\n            </div>\n          </div>\n        </div>\n\n        <!-- Espresso -->\n        <div class=\"brew-panel\" id=\"panel-espresso\">\n          <div class=\"brew-visual\">\n            <div class=\"brew-glow\"></div>\n            <div class=\"brew-diagram\">\n              <svg width=\"200\" height=\"280\" viewBox=\"0 0 200 280\" fill=\"none\">\n                <!-- Machine body -->\n                <rect x=\"40\" y=\"80\" width=\"120\" height=\"100\" rx=\"6\" fill=\"url(#esp1)\" stroke=\"rgba(200,114,10,0.2)\" stroke-width=\"1\"/>\n                <!-- Group head -->\n                <rect x=\"70\" y=\"175\" width=\"60\" height=\"20\" rx=\"3\" fill=\"#3a2010\"/>\n                <!-- Portafilter -->\n                <path d=\"M 75 195 L 65 230 L 135 230 L 125 195 Z\" fill=\"url(#esp2)\"/>\n                <!-- Spouts -->\n                <line x1=\"90\" y1=\"230\" x2=\"85\" y2=\"260\" stroke=\"#8b4a1a\" stroke-width=\"3\" stroke-linecap=\"round\"/>\n                <line x1=\"110\" y1=\"230\" x2=\"115\" y2=\"260\" stroke=\"#8b4a1a\" stroke-width=\"3\" stroke-linecap=\"round\"/>\n                <!-- Espresso drops -->\n                <ellipse cx=\"85\" cy=\"264\" rx=\"4\" ry=\"5\" fill=\"#6b3a14\" opacity=\"0.8\"/>\n                <ellipse cx=\"115\" cy=\"264\" rx=\"4\" ry=\"5\" fill=\"#6b3a14\" opacity=\"0.8\"/>\n                <!-- Cup -->\n                <path d=\"M 75 265 Q 72 285 100 288 Q 128 285 125 265 Z\" fill=\"url(#esp2)\"/>\n                <!-- Pressure gauge -->\n                <circle cx=\"100\" cy=\"125\" r=\"22\" fill=\"none\" stroke=\"rgba(200,114,10,0.3)\" stroke-width=\"1.5\"/>\n                <circle cx=\"100\" cy=\"125\" r=\"16\" fill=\"rgba(0,0,0,0.3)\"/>\n                <line x1=\"100\" y1=\"125\" x2=\"110\" y2=\"112\" stroke=\"var(--amber)\" stroke-width=\"2\" stroke-linecap=\"round\"/>\n                <!-- Steam wand -->\n                <line x1=\"155\" y1=\"120\" x2=\"162\" y2=\"180\" stroke=\"#4a2412\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n                <defs>\n                  <linearGradient id=\"esp1\" x1=\"40\" y1=\"80\" x2=\"160\" y2=\"180\" gradientUnits=\"userSpaceOnUse\">\n                    <stop offset=\"0%\" stop-color=\"#3a2010\"/>\n                    <stop offset=\"100%\" stop-color=\"#2d1a0d\"/>\n                  </linearGradient>\n                  <linearGradient id=\"esp2\" x1=\"65\" y1=\"195\" x2=\"135\" y2=\"290\" gradientUnits=\"userSpaceOnUse\">\n                    <stop offset=\"0%\" stop-color=\"#4a2412\"/>\n                    <stop offset=\"100%\" stop-color=\"#2d1a0d\"/>\n                  </linearGradient>\n                </defs>\n              </svg>\n            </div>\n          </div>\n          <div class=\"brew-steps\">\n            <div class=\"brew-step\">\n              <div class=\"step-num\">01</div>\n              <div class=\"step-title\">Dose</div>\n              <div class=\"step-desc\">18g fine ground \u00b7 9 bars pressure \u00b7 93\u00b0C water</div>\n            </div>\n            <div class=\"brew-step\">\n              <div class=\"step-num\">02</div>\n              <div class=\"step-title\">Tamp</div>\n              <div class=\"step-desc\">30 lbs even pressure \u00b7 Level puck \u00b7 Check edges</div>\n            </div>\n            <div class=\"brew-step\">\n              <div class=\"step-num\">03</div>\n              <div class=\"step-title\">Pull</div>\n              <div class=\"step-desc\">36g yield \u00b7 27\u201332 second extraction \u00b7 Rich crema</div>\n            </div>\n          </div>\n        </div>\n\n        <!-- Cold Brew -->\n        <div class=\"brew-panel\" id=\"panel-coldbrewed\">\n          <div class=\"brew-visual\">\n            <div class=\"brew-glow\"></div>\n            <div class=\"brew-diagram\">\n              <svg width=\"200\" height=\"280\" viewBox=\"0 0 200 280\" fill=\"none\">\n                <!-- Mason jar -->\n                <rect x=\"55\" y=\"60\" width=\"90\" height=\"190\" rx=\"8\" fill=\"url(#cb1)\" stroke=\"rgba(200,114,10,0.2)\" stroke-width=\"1\"/>\n                <!-- Lid -->\n                <rect x=\"50\" y=\"48\" width=\"100\" height=\"18\" rx=\"4\" fill=\"#3a2010\" stroke=\"rgba(200,114,10,0.3)\" stroke-width=\"1\"/>\n                <!-- Coffee liquid -->\n                <rect x=\"57\" y=\"120\" width=\"86\" height=\"128\" rx=\"4\" fill=\"url(#cb2)\" opacity=\"0.85\"/>\n                <!-- Ice cubes -->\n                <rect x=\"68\" y=\"128\" width=\"20\" height=\"20\" rx=\"2\" fill=\"rgba(200,220,240,0.15)\" stroke=\"rgba(200,230,255,0.2)\" stroke-width=\"1\"/>\n                <rect x=\"92\" y=\"135\" width=\"18\" height=\"18\" rx=\"2\" fill=\"rgba(200,220,240,0.12)\" stroke=\"rgba(200,230,255,0.15)\" stroke-width=\"1\"/>\n                <rect x=\"114\" y=\"130\" width=\"16\" height=\"16\" rx=\"2\" fill=\"rgba(200,220,240,0.1)\" stroke=\"rgba(200,230,255,0.12)\" stroke-width=\"1\"/>\n                <!-- Reflection -->\n                <path d=\"M 60 65 L 60 240\" stroke=\"rgba(255,255,255,0.06)\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n                <defs>\n                  <linearGradient id=\"cb1\" x1=\"55\" y1=\"60\" x2=\"145\" y2=\"250\" gradientUnits=\"userSpaceOnUse\">\n                    <stop offset=\"0%\" stop-color=\"#2d1a0d\" stop-opacity=\"0.6\"/>\n                    <stop offset=\"100%\" stop-color=\"#1e1008\" stop-opacity=\"0.8\"/>\n                  </linearGradient>\n                  <linearGradient id=\"cb2\" x1=\"57\" y1=\"120\" x2=\"143\" y2=\"248\" gradientUnits=\"userSpaceOnUse\">\n                    <stop offset=\"0%\" stop-color=\"#5a2e10\"/>\n                    <stop offset=\"100%\" stop-color=\"#3a1c0a\"/>\n                  </linearGradient>\n                </defs>\n              </svg>\n            </div>\n          </div>\n          <div class=\"brew-steps\">\n            <div class=\"brew-step\">\n              <div class=\"step-num\">01</div>\n              <div class=\"step-title\">Grind</div>\n              <div class=\"step-desc\">100g coarse ground \u00b7 1:8 ratio \u00b7 Cold filtered water</div>\n            </div>\n            <div class=\"brew-step\">\n              <div class=\"step-num\">02</div>\n              <div class=\"step-title\">Steep</div>\n              <div class=\"step-desc\">18\u201324 hours \u00b7 4\u00b0C refrigerator \u00b7 No agitation</div>\n            </div>\n            <div class=\"brew-step\">\n              <div class=\"step-num\">03</div>\n              <div class=\"step-title\">Serve</div>\n              <div class=\"step-desc\">Strain twice \u00b7 Dilute 1:1 \u00b7 Over ice \u00b7 2-week shelf life</div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- Manifesto -->\n  <section class=\"manifesto\" id=\"about\">\n    <div class=\"section-label reveal\" style=\"justify-content:center;\">Our Philosophy</div>\n    <p class=\"manifesto-quote reveal reveal-delay-1\">\n      \"Coffee is not a commodity. It is a conversation between\n      <em>a farmer, a roaster, and a moment</em> \u2014 mediated by water and fire.\"\n    </p>\n    <div class=\"manifesto-attr reveal reveal-delay-2\">\u2014 Terroir Roasters, Founded 2019</div>\n  </section>\n\n  <!-- Newsletter -->\n  <section class=\"newsletter\">\n    <div class=\"newsletter-inner\">\n      <div class=\"section-label reveal\" style=\"justify-content:center;\">Stay Connected</div>\n      <h2 class=\"newsletter-title reveal reveal-delay-1\">\n        The Weekly<br/><em>Cupping Notes</em>\n      </h2>\n      <p class=\"newsletter-sub reveal reveal-delay-2\">\n        Harvest reports, brew guides, and limited micro-lots \u2014 delivered to your inbox\n        before they sell out. No noise, only signal.\n      </p>\n      <form class=\"newsletter-form reveal reveal-delay-3\" onsubmit=\"handleSubmit(event)\">\n        <input type=\"email\" class=\"newsletter-input\" placeholder=\"your@email.com\" required />\n        <button type=\"submit\" class=\"newsletter-btn\">Subscribe</button>\n      </form>\n    </div>\n  </section>\n\n  <!-- Footer -->\n  <footer>\n    <div class=\"footer-top\">\n      <div class=\"footer-brand\">\n        <span class=\"footer-logo\">Terroir</span>\n        <p class=\"footer-tagline\">Where the land speaks<br/>through the cup.</p>\n      </div>\n      <div class=\"footer-col\">\n        <h4>Coffees</h4>\n        <ul>\n          <li><a href=\"#\">Single Origins</a></li>\n          <li><a href=\"#\">Blends</a></li>\n          <li><a href=\"#\">Espresso</a></li>\n          <li><a href=\"#\">Decaf</a></li>\n          <li><a href=\"#\">Subscriptions</a></li>\n        </ul>\n      </div>\n      <div class=\"footer-col\">\n        <h4>Learn</h4>\n        <ul>\n          <li><a href=\"#\">Brew Guides</a></li>\n          <li><a href=\"#\">Farm Stories</a></li>\n          <li><a href=\"#\">Cupping Notes</a></li>\n          <li><a href=\"#\">Roast Journal</a></li>\n        </ul>\n      </div>\n      <div class=\"footer-col\">\n        <h4>Company</h4>\n        <ul>\n          <li><a href=\"#\">About Us</a></li>\n          <li><a href=\"#\">Direct Trade</a></li>\n          <li><a href=\"#\">Wholesale</a></li>\n          <li><a href=\"#\">Contact</a></li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"footer-bottom\">\n      <div class=\"footer-copy\">\u00a9 2024 Terroir Roasters \u00b7 Crafted with obsession</div>\n      <div class=\"footer-socials\">\n        <a href=\"#\">Instagram</a>\n        <a href=\"#\">Twitter</a>\n        <a href=\"#\">Substack</a>\n      </div>\n    </div>\n  </footer>\n\n  <script>\n    // Custom cursor\n    const dot = document.getElementById('cursorDot');\n    const ring = document.getElementById('cursorRing');\n    let mouseX = 0, mouseY = 0, ringX = 0, ringY = 0;\n\n    document.addEventListener('mousemove', e => {\n      mouseX = e.clientX; mouseY = e.clientY;\n      dot.style.left = mouseX + 'px';\n      dot.style.top  = mouseY + 'px';\n    });\n\n    (function animRing() {\n      ringX += (mouseX - ringX) * 0.12;\n      ringY += (mouseY - ringY) * 0.12;\n      ring.style.left = ringX + 'px';\n      ring.style.top  = ringY + 'px';\n      requestAnimationFrame(animRing);\n    })();\n\n    document.querySelectorAll('a, button, .roast-item, .origin-card, .brew-tab').forEach(el => {\n      el.addEventListener('mouseenter', () => document.body.classList.add('hovering'));\n      el.addEventListener('mouseleave', () => document.body.classList.remove('hovering'));\n    });\n\n    // Scroll-based nav\n    const nav = document.getElementById('nav');\n    window.addEventListener('scroll', () => {\n      nav.classList.toggle('scrolled', window.scrollY > 60);\n    }, { passive: true });\n\n    // Scroll reveal\n    const revealEls = document.querySelectorAll('.reveal');\n    const io = new IntersectionObserver(entries => {\n      entries.forEach(e => { if (e.isIntersecting) { e.target.classList.add('visible'); io.unobserve(e.target); } });\n    }, { threshold: 0.12 });\n    revealEls.forEach(el => io.observe(el));\n\n    // Brew tabs\n    document.querySelectorAll('.brew-tab').forEach(tab => {\n      tab.addEventListener('click', () => {\n        document.querySelectorAll('.brew-tab').forEach(t => t.classList.remove('active'));\n        document.querySelectorAll('.brew-panel').forEach(p => p.classList.remove('active'));\n        tab.classList.add('active');\n        const panel = document.getElementById('panel-' + tab.dataset.panel);\n        if (panel) panel.classList.add('active');\n      });\n    });\n\n    // Newsletter\n    function handleSubmit(e) {\n      e.preventDefault();\n      const btn = e.target.querySelector('.newsletter-btn');\n      btn.textContent = 'Subscribed \u2713';\n      btn.style.background = 'var(--gold)';\n      setTimeout(() => { btn.textContent = 'Subscribe'; btn.style.background = ''; }, 3000);\n    }\n\n    // Roast add buttons\n    document.querySelectorAll('.roast-add').forEach(btn => {\n      btn.addEventListener('click', () => {\n        const orig = btn.textContent;\n        btn.textContent = '\u2713';\n        setTimeout(() => btn.textContent = orig, 1500);\n      });\n    });\n  </script>\n</body>\n</html>\n";
